-- VFDA VA Quiz App - Training program database changes (training bank, 4-week doctor training program, sessions).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after weekly-summary.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261118140000_training_program.sql =====

-- The training bank and the 4-week doctor training program (8 sessions, 2 a
-- week), built once a VA has submitted all their scheduled quiz days (W2D5,
-- or their last scheduled day). One program per VA and office; VFDA's
-- "Generate training program now" (testing) replaces it.
--
-- training_programs.bank: { knows: [...], practice: [...], notCovered }.
-- training_sessions.sheet: the Training Sheet (what you'll go through,
-- agenda, 5 scenarios, wrap-up); VFDA may edit it before it's sent.
-- Sending is Sunday night in the office's time zone, starting the first
-- Sunday after the trigger (start_sunday), for 4 weeks. Every send is a
-- notifications row (va_id, event program:<id>:...), so nothing goes twice.
--
-- Safe to run more than once.

create table if not exists public.training_programs (
  id            uuid primary key default gen_random_uuid(),
  va_id         uuid not null references public.profiles (id) on delete cascade,
  office_id     uuid not null references public.offices (id) on delete cascade,
  status        text not null default 'building' check (status in ('building', 'ready', 'running', 'done', 'failed')),
  trigger       text not null default 'auto' check (trigger in ('auto', 'test')),
  missing_days  jsonb not null default '[]'::jsonb, -- scheduled days not submitted (test builds only)
  bank          jsonb,
  start_sunday  date,
  error         text,
  built_at      timestamptz,
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (va_id, office_id)
);
create index if not exists training_programs_office_id_idx on public.training_programs (office_id);

create table if not exists public.training_sessions (
  id          uuid primary key default gen_random_uuid(),
  program_id  uuid not null references public.training_programs (id) on delete cascade,
  va_id       uuid not null references public.profiles (id) on delete cascade,
  office_id   uuid not null references public.offices (id) on delete cascade,
  number      integer not null check (number between 1 and 8),
  week        integer not null check (week between 1 and 4),
  send_on     date,
  focus       jsonb not null,
  strength    jsonb not null,
  sheet       jsonb,
  status      text not null default 'scheduled' check (status in ('scheduled', 'sent', 'done')),
  sent_at     timestamptz,
  done_at     timestamptz,
  done_note   text,
  done_by     uuid references public.profiles (id) on delete set null,
  edited_at   timestamptz,
  edited_by   uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (program_id, number)
);
create index if not exists training_sessions_office_id_idx on public.training_sessions (office_id);

drop trigger if exists set_updated_at on public.training_programs;
create trigger set_updated_at before update on public.training_programs
  for each row execute function private.set_updated_at();
drop trigger if exists set_updated_at on public.training_sessions;
create trigger set_updated_at before update on public.training_sessions
  for each row execute function private.set_updated_at();

-- VFDA: everything. Doctors: read their own office's programs (they mark
-- sessions done through the server). VAs: nothing (they get a Sunday email).
alter table public.training_programs enable row level security;
drop policy if exists "admin full access" on public.training_programs;
create policy "admin full access" on public.training_programs for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
drop policy if exists "doctor reads own office programs" on public.training_programs;
create policy "doctor reads own office programs" on public.training_programs for select to authenticated
  using (private.is_doctor_of_office(office_id));

alter table public.training_sessions enable row level security;
drop policy if exists "admin full access" on public.training_sessions;
create policy "admin full access" on public.training_sessions for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
drop policy if exists "doctor reads own office sessions" on public.training_sessions;
create policy "doctor reads own office sessions" on public.training_sessions for select to authenticated
  using (private.is_doctor_of_office(office_id));

commit;
